use xiom.io;
type Room = {
  description: Str;
  has_torch: Bool;
  torch_lit: Bool;
}

fn describe(room: &Room) -> Str {
  if room.torch_lit {
    "The room is brightly lit by a flickering torch."
  } else {
    "The room is pitch black. You can't see anything."
  }
}

fn handle_command(cmd: Str, room: &mut Room) -> Str {
  if cmd == "look" {
    return describe(room);
  };
  if cmd == "light torch" && room.has_torch && !room.torch_lit {
    room.torch_lit = true;
    return "You light the torch. The room illuminates.";
  };
  if cmd == "extinguish torch" && room.torch_lit {
    room.torch_lit = false;
    return "You extinguish the torch. Darkness returns.";
  };
  "You can't do that."
}

fn main() -> Int {
  var room = Room{ description: "", has_torch: true, torch_lit: false };
  io.println(handle_command("look", &mut room));
  io.println(handle_command("light torch", &mut room));
  io.println(handle_command("look", &mut room));
  return 0;
}
